static const size_t FOURD_BUILTIN_COUNT =
    sizeof(FOURD_BUILTINS) / sizeof(FOURD_BUILTINS[0]);

// ---------------------------------------------------------------- lookup

// Index of the first entry not ordered before `key` (comparing `len` bytes).
static size_t fourd_lower_bound(const char *key, size_t len) {
  size_t lo = 0, hi = FOURD_BUILTIN_COUNT;
  while (lo < hi) {
    size_t mid = lo + (hi - lo) / 2;
    if (fourd_strnicmp(FOURD_BUILTINS[mid].name, key, len) < 0) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }
  return lo;
}

// Returns the kind mask for an exact match, or 0. Exactly one bit is ever set;
// the mask type exists so the scanner can AND against valid_symbols cheaply.
static unsigned char fourd_builtin_kind(const char *name) {
  size_t len = strlen(name);
  if (len == 0 || len >= FOURD_MAX_BUILTIN_LEN) return 0;
  size_t i = fourd_lower_bound(name, len);
  if (i >= FOURD_BUILTIN_COUNT) return 0;
  if (fourd_stricmp(FOURD_BUILTINS[i].name, name) != 0) return 0;
  return FOURD_BUILTINS[i].kind;
}

// True if any builtin *starts with* `name`. Drives the early bailout in
// scan_builtin(): once nothing extends the accumulated prefix, more words
// cannot help, so ordinary identifiers stop dragging the lexer forward.
static bool is_builtin_prefix(const char *name) {
  size_t len = strlen(name);
  if (len == 0 || len >= FOURD_MAX_BUILTIN_LEN) return false;
  size_t i = fourd_lower_bound(name, len);
  return i < FOURD_BUILTIN_COUNT &&
         fourd_strnicmp(FOURD_BUILTINS[i].name, name, len) == 0;
}

// ---------------------------------------------------------------- debug check

#ifndef NDEBUG
// Call once from tree_sitter_fourd_external_scanner_create() while developing.
static bool fourd_builtins_sorted(void) {
  for (size_t i = 1; i < FOURD_BUILTIN_COUNT; i++) {
    if (fourd_stricmp(FOURD_BUILTINS[i - 1].name, FOURD_BUILTINS[i].name) >= 0) {
      return false;
    }
  }
  return true;
}
#endif

#endif  // TREE_SITTER_FOURD_BUILTINS_H_
